    m = model('task011_live_exact', nodes, inits, output_dtype=9, opset=12, value_infos=value_infos)
    g = m.graph

    # The chosen mini-cell is the only 3x3 block without colour 8.  A stride-4
    # 3x3 convolution counts colour-8 pixels in every mini-cell at once, replacing
    # nine separate Slice+ReduceSum blocks.
    noise_idx = next(i for i, node in enumerate(g.node) if node.output and node.output[0] == 'noise_sums')
    del g.node[:noise_idx + 1]
    noise_w = np.zeros((1, 10, 3, 3), dtype=np.float32)
    noise_w[0, 8, :, :] = 1.0
    extra_inits = [
        numpy_helper.from_array(noise_w, name='noise_conv_w'),
        numpy_helper.from_array(np.array([0, 0], dtype=np.int64), name='noise_grid_starts'),
        numpy_helper.from_array(np.array([3, 3], dtype=np.int64), name='noise_grid_ends'),
        numpy_helper.from_array(np.array([2, 3], dtype=np.int64), name='noise_grid_axes'),
        numpy_helper.from_array(np.array([9], dtype=np.int64), name='noise_shape'),
    ]
    g.initializer.extend(extra_inits)
    compact_noise_nodes = [
        helper.make_node('Conv', ['input', 'noise_conv_w'], ['noise_grid7'], kernel_shape=[3, 3], strides=[4, 4]),
        helper.make_node('Slice', ['noise_grid7', 'noise_grid_starts', 'noise_grid_ends', 'noise_grid_axes'], ['noise_grid']),
        helper.make_node('Reshape', ['noise_grid', 'noise_shape'], ['noise_sums']),
    ]
    for node in reversed(compact_noise_nodes):
        g.node.insert(0, node)

    used_inputs = set()
    for node in g.node:
        used_inputs.update(node.input)
    kept_inits = [init for init in g.initializer if init.name in used_inputs]
    g.ClearField('initializer')
    g.initializer.extend(kept_inits)
    g.value_info.extend([
        helper.make_tensor_value_info('noise_grid7', TensorProto.FLOAT, [1, 1, 7, 7]),
        helper.make_tensor_value_info('noise_grid', TensorProto.FLOAT, [1, 1, 3, 3]),
        helper.make_tensor_value_info('noise_sums', TensorProto.FLOAT, [9]),
    ])
    return m
